  const sensors = [...IOT_TANK_STEPS].reverse().map((s) => ({ tag: s.tag, on: iotSwitchOn(t[s.key]) }));
  return { pct: step ? step.pct : 0, label: step ? step.label : "Empty", sensors, has: !!tankLevel };
